export function parseWalkMinutes(input){const s=input.trim();if(s==='')return {kind:'blank',value:null};if(!/^[0-9]+$/.test(s)||Number(s)>60)return {kind:'invalid',value:null};return {kind:'number',value:Number(s)};}
