export function clockWalkView(state){if(!own(state,'courierClockWalk'))return {status:'missing',readable:[],unreadable:[]};const root=state.courierClockWalk;if(!object(root)||root.version!==1||!(root.current===null||id(root.current))||!object(root.cases))return {status:'recovery',root,readable:[],unreadable:[]};const readable=[],unreadable=[];for(const [key,w]of Object.entries(root.cases)){const v=id(key)&&workView(w,key);(v?readable:unreadable).push(v?{id:key,...v}:{id:key,raw:w});}return {status:'ready',root,readable,unreadable,...(readable.find(x=>x.id===root.current)||{})};}
const fresh=()=>({version:1,current:null,cases:{}});
function fits(state,root,canExport){try{const c={...state,courierClockWalk:root};return recoveryFitsProgressLimits(c)&&canExport(c)===true;}catch{return false;}}
